const items = $input.all();

return items.flatMap(item => {
  const json = item.json ?? {};
  const body = json.body ?? {};
  const eventId = Number(body.eventId ?? json.eventId ?? json.id);
  const analysisIdValue = body.analysisId ?? json.analysisId;
  const analysisId = analysisIdValue === undefined || analysisIdValue === null || analysisIdValue === '' ? null : Number(analysisIdValue);

  if (!Number.isInteger(eventId) || eventId <= 0) {
    return [];
  }

  return [{
    json: {
      eventId,
      analysisId: Number.isInteger(analysisId) && analysisId > 0 ? analysisId : null,
      channel: body.channel ?? json.channel ?? 'TELEGRAM',
      tone: body.tone ?? json.tone ?? 'INFORMATIVO',
      length: body.length ?? json.length ?? 'STANDARD'
    }
  }];
});
